INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(13149, 'plPL', 'Rozwiewanie złudzeń', 'Zawsze się wtrącają...$b$bNieskończone Stado chce zakłócić bieg historii, jaką znamy, zwodząc księcia Arthasa.$b$bJeśli zdołają go przekonać, że żadne tutejsze zboże nie jest zarażone, nigdy nie będzie musiał podjąć brzemiennej w skutki decyzji o wyrżnięciu Stratholmu.$b$bDo tego nie może dojść.$b$bUżyj tego tajemnego zakłócacza na każdej podejrzanej skrzyni ze zbożem, jaką znajdziesz, by ujawnić jej prawdziwą naturę. Gdy skończysz, spotkaj się ze mną przy wejściu do Stratholmu, na północ stąd.', 'Chromie chce, abyś $gużył:użyła; tajemnego zakłócacza na podejrzanych skrzyniach w dawnym Stratholmie, a potem $gporozmawiał:porozmawiała; z nią przy wejściu do Stratholmu.', '', 'Wróć do Chromie w Rzezi Stratholmu.', 'Rozwiane skrzynie zarażonego zboża', '', '', '', 0),
(13151, 'plPL', 'Królewska eskorta', 'Nieskończone Stado raczej nie podda się tak łatwo. Nie wiem na pewno, co knują, ale coś mi mówi, że to nie ostatnie nasze dzisiejsze spotkanie.$b$bZa chwilę Arthas stanie przed rozpaczliwym dylematem i podejmie doniosłą decyzję.$b$bNie trać teraz czujności, $n. Nie muszę ci przypominać, jak wiele jest na szali. Muszę cię prosić, byś $gtowarzyszył:towarzyszyła; księciu, gdy będzie wyrzynał Stratholm.$b$bArthas musi przejść przez Stratholm żywy, a ty musisz dopilnować, by pokonał Mal\'Ganisa!', 'Chromie prosi, abyś $gtowarzyszył:towarzyszyła; Arthasowi w Rzezi Stratholmu. Gdy Mal\'Ganis zostanie pokonany, masz ponownie z nią porozmawiać.', '', 'Wróć do Chromie w Rzezi Stratholmu.', 'Pokonany Mal\'Ganis', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(13149, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, przyjacielu. Żołnierze Arthasa zobaczyli zarażone zboże.$b$bA teraz słuchaj uważnie. Jeszcze wiele zostało do zrobienia.', 0),
(13151, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, $N.$b$bPlany Nieskończonych zostały udaremnione, a ta nić historii pozostała nienaruszona.$b$bDziękuję ci za twoją nieocenioną pomoc, podobnie jak całe Brązowe Stado.', 0),
(13243, 'plPL', 'Na razie jesteśmy ocaleni. Dziękuję.$b$bNiestety, z uwagi na naturę ich ingerencji Nieskończeni będą mieli niemal nieograniczone możliwości, by spróbować ponownie.$b$bJedno potrafię dostrzec: w przyszłości to ty znajdziesz się w samym sercu walki, by ich powstrzymać, $N!', 0),
(13251, 'plPL', 'Niesamowite! Nigdy nie widziałem czegoś takiego. Dopilnuję, by trafiło we właściwe ręce w Purpurowej Cytadeli.$b$bGdyby tylko pozwolono ci zmienić bieg historii. Może gdyby powstrzymać Arthasa przed... nie, ta droga prowadzi do szaleństwa.$b$bStrażnicy Czasu z pewnością wiedzą najlepiej, co robić w tych sprawach.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(13243, 'plPL', 'Czas zawsze jest cennym zasobem, ale w tym przypadku szczególnie, $N. Proszę, rozpraw się z agentami Nieskończonego Stada, zanim będzie za późno!', 0),
(13251, 'plPL', 'Musimy wykorzystać błąd Mal\'Ganisa. Nie co dzień trafia się taka okazja.$b$bJeśli zdołamy zbadać ten artefakt, być może lepiej zrozumiemy nathrezimów!', 0);
