INSERT INTO `item_template_locale` (`ID`, `locale`, `Name`, `Description`, `VerifiedBuild`) VALUES
(37115, 'plPL', 'Naramienniki z Placu Krzyżowców', '', 0),
(37116, 'plPL', 'Epolety z Alei Targowej', '', 0),
(37117, 'plPL', 'Karwasze z Placu Królewskiego', '', 0),
