(43327, 'plPL', 'Lilia ze Stratholmu', '', 0),
(43697, 'plPL', 'Artefakt z ojczystego świata nathrezimów', 'Cóż za dziwna konstrukcja. To chyba jeden z najbardziej obco wyglądających przedmiotów, jakie kiedykolwiek $gwidziałeś:widziałaś;.', 0),
