INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(27915, 1, 0, 'plPL', 'Poszukiwacze przygód, musicie się spieszyć! Strażnik Czasu długo już nie wytrzyma!'),
(27915, 2, 0, 'plPL', 'Ledwo wyczuwam Strażnika Czasu! Jego linia czasu szybko się rozmywa!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(27044, 'plPL', '', 'Witaj, $gposzukiwaczu:poszukiwaczko; przygód. $GPrzybyłeś:Przybyłaś; w ostatniej chwili.', 0),
(27090, 'plPL', 'Dlaczego cofnięto mnie właśnie do tego miejsca i czasu?', 'Dlaczego cofnięto mnie właśnie do tego miejsca i czasu?', 0),
(27091, 'plPL', '', 'Nieskończone Stado próbuje zmienić przeznaczenie księcia Arthasa Menethila.$B$BZnasz go teraz jako Króla Lisza, ale tu i teraz był jeszcze księciem Lordaeronu, który starał się zrobić to, co najlepsze dla swojego królestwa.$B$BArthas podejmuje dziś niezwykle brzemienną w skutki decyzję, która prowadzi do czegoś, co my, Strażnicy Czasu, nazywamy punktem zwrotnym linii czasu.', 0),
(27092, 'plPL', 'Jaka to była decyzja?', 'Jaka to była decyzja?', 0),
(27093, 'plPL', '', 'Arthas wydał rozkaz wyrżnięcia Stratholmu – zabicia każdego człowieka w jego murach.$B$BOdkrył dowody na to, że Plaga zaraziła miasto swoją podstępną zarazą, a ta choroba nie tylko zabija ludzi.$B$BCi, którzy umrą od tej zarazy, powstają jako bezmyślne zombie i zasilają machinę wojenną Plagi.', 0),
(27094, 'plPL', 'Jak więc Nieskończone Stado zamierza się wtrącić?', 'Jak więc Nieskończone Stado zamierza się wtrącić?', 0),
(27102, 'plPL', '', 'Nieskończeni próbują czegoś niezwykle subtelnego jak na siebie. Starają się ukryć dowody, które skłonią Arthasa do decyzji o wyrżnięciu Stratholmu.$B$BIch agenci rzucili iluzję na transporty zarażonego zboża w okolicy, by wyglądały na zwyczajne.$B$BMusisz odnaleźć ukryte zboże i użyć na transportach tego tajemnego zakłócacza. Ludzie Arthasa szukają zarażonego zboża i gdy iluzja zniknie, szybko je znajdą.', 0),
(27191, 'plPL', 'Panie Perelli, widział pan jakieś ślady nieumarłych? Książę Arthas będzie wdzięczny za wszelkie informacje.', '', 0),
(27192, 'plPL', 'Panie Perelli, wiem, że sporo pan podróżuje i zachwala swoje towary. Na pewno słyszał pan jakieś pogłoski albo wieści o Pladze?', '', 0),
(27193, 'plPL', 'Czy zamierza pan wkrótce opuścić okolicę, gdybyśmy mieli dalsze pytania?', '', 0),
(27194, 'plPL', 'Panie Perelli, czy te towary były przez cały czas pod pańskim nadzorem?', '', 0),
(27195, 'plPL', 'Nie ma pan przypadkiem puszkowanej zupy żółwiowej z Międzygórza?', '', 0),
(27197, 'plPL', 'Panie Perelli, jeśli podczas podróży natknie się pan na ślady działalności Plagi albo podejrzane interesy, proszę zawiadomić najbliższego żołnierza Lordaeronu.', '', 0),
(27198, 'plPL', 'Nie, sierżancie.', '', 0),
(27199, 'plPL', 'Nie, panie.', '', 0),
(27200, 'plPL', 'Nie.', '', 0),
(27201, 'plPL', 'Tak, panie.', '', 0),
(27202, 'plPL', 'Tak, sierżancie Morigan.', '', 0),
(27205, 'plPL', 'Nie ma pan nic przeciwko, żebym sprawdził, czy nikt nie majstrował przy pańskim towarze?', '', 0),
(27206, 'plPL', 'Chwileczkę, co to jest? Ukrywał pan coś przede mną, Perelli!', '', 0),
(27208, 'plPL', 'O czym pan mówi, sierżancie!', '', 0),
(27210, 'plPL', 'Konfiskuję to podejrzane zboże, Perelli. Szukaliśmy śladów zatrutej żywności i w pańskim interesie jest zostać na miejscu, dopóki książę Arthas tego nie sprawdzi.', '', 0),
(27213, 'plPL', 'Musi mi pan uwierzyć, jestem niewinny!', '', 0),
(27216, 'plPL', 'Zobaczymy, Perelli. Zobaczymy.', '', 0),
(27219, 'plPL', '', 'Zobaczmy, wczoraj na kolację był kurczak.', 0),
(27220, 'plPL', '', 'Mam mnóstwo wędzonego boczku, ale jadł go na śniadanie.', 0),
(27221, 'plPL', '', 'Muszę mu przygotować coś zdrowego, wciąż nie doszedł do siebie po tej chorobie z zeszłego tygodnia.', 0),
(27222, 'plPL', '', 'Truskawki! Och, zaraz, to nie ich pora.', 0),
(27224, 'plPL', '', 'Martho, skończyła mi się mąka na chleb. Nie masz przypadkiem zboża z tej ostatniej dostawy?', 0),
(27229, 'plPL', '', 'Dzięki, Martho! Mam u ciebie dług.', 0),
(27230, 'plPL', '', 'O rety.', 0),
(27231, 'plPL', '', 'Martho, coś jest nie tak z tym zbożem! Żołnierze księcia właśnie czegoś takiego szukali. Pójdę któregoś poszukać.', 0),
(27232, 'plPL', '', 'Och, witaj, Jeno. Oczywiście, że możesz pożyczyć trochę zboża. Częstuj się.', 0),
(27235, 'plPL', '', 'Ojej.', 0),
(27247, 'plPL', 'Dobra, na razie dość pracy. Czas na coś do picia i pogawędkę w karczmie.', '', 0),
(27248, 'plPL', 'Zaraz, co to za smród?', '', 0),
(27249, 'plPL', 'To nie mogę być ja, kąpałem się 3 dni temu!', '', 0),
(27250, 'plPL', 'Uff, było blisko. To tylko to zboże.', '', 0),
(27252, 'plPL', 'Chwileczkę. Zboże nie powinno tak śmierdzieć! Lepiej pójdę poszukać strażnika.', '', 0),
(27253, 'plPL', 'Wiedziałem, że powinienem był lepiej zabezpieczyć zamek wozu, kiedy byłem w Andorhal.', '', 0),
(27254, 'plPL', 'Z tą dostawą zboża są same kłopoty!', '', 0),
(27255, 'plPL', 'Przez to stracę premię za terminowość!', '', 0),
(27256, 'plPL', 'Miało mnie tu dziś w ogóle nie być!', '', 0),
(27257, 'plPL', 'No cóż, chyba trzeba załadować wszystko z powrotem na wóz.', '', 0),
(27258, 'plPL', 'No nie! Wóz mi się zepsuł, koń zgubił podkowę, a teraz jeszcze ładunek się psuje!', '', 0),
(27259, 'plPL', 'Chyba pójdę poszukać władz. Jak dobrze pójdzie, powiedzą mi, że to zaraza i wszyscy umrzemy.', '', 0),
(27265, 'plPL', '', 'Dobra robota! Arthas wie już o zarażonym zbożu w Stratholmie i zaraz rozpocznie rzeź.$B$BCoś jednak wciąż jest nie tak. Wyczuwam w tej linii czasu obcą obecność poza nami, a to znaczy, że gdzieś tu musi być Nieskończone Stado.', 0),
(27266, 'plPL', 'Jak myślisz, co knują?', 'Jak myślisz, co knują?', 0),
(27267, 'plPL', '', 'Nie wiem i to mnie martwi. Zrobię wszystko, by odnaleźć Nieskończonych.$B$BTy natomiast musisz trzymać się blisko Arthasa i przyłączyć się do jego armii.', 0),
(27268, 'plPL', 'Że co mam zrobić?', 'Że co mam zrobić?', 0),
(27269, 'plPL', '', 'No, nie będziesz podpisywać papierów rekrutacyjnych ani nic takiego, ale będziesz walczyć u jego boku.$B$BMusisz dopilnować, by Arthas wyrżnął Stratholm i pokonał Mal\'Ganisa. Bez Uthera i Jainy będzie potrzebował wszelkiej możliwej pomocy.$B$BJeśli porozmawiasz z Arthasem, każe ci niszczyć siły Mal\'Ganisa. Trzymaj się go, dopóki nie dowiem się, co knują Nieskończeni.', 0),
(27270, 'plPL', 'Dobrze, Chromie.', 'Dobrze, Chromie.', 0),
(27271, 'plPL', '', 'Powodzenia i uważaj na siebie. O, nadchodzą Uther i Jaina.', 0),
(27314, 'plPL', 'Dobrze, że jesteś, Utherze.', '', 0),
(27316, 'plPL', 'Jakbym mógł zapomnieć. Słuchaj, Utherze, jest coś, co powinieneś wiedzieć o zarazie...', '', 0),
(27317, 'plPL', 'O nie. Spóźniliśmy się. Wszyscy ci ludzie są zarażeni! Teraz mogą wyglądać na zdrowych, ale to tylko kwestia czasu, nim zmienią się w nieumarłych!', '', 0),
(27319, 'plPL', 'Całe to miasto trzeba oczyścić.', '', 0),
(27321, 'plPL', 'Do diabła, Utherze! Jako twój przyszły król rozkazuję ci oczyścić to miasto!', '', 0),
(27323, 'plPL', 'W takim razie muszę to uznać za akt zdrady.', '', 0),
(27325, 'plPL', 'Doprawdy? Lordzie Utherze, na mocy mojego prawa do sukcesji i zwierzchnictwa mojej korony niniejszym odbieram ci dowództwo i zawieszam twoich paladynów w służbie.', '', 0),
(27327, 'plPL', 'Stało się! Ci z was, którzy mają wolę ocalić tę ziemię, za mną! Reszta... zejdźcie mi z oczu!', '', 0),
(27329, 'plPL', 'Jaino?', '', 0),
(27466, 'plPL', 'Zajmijcie tu pozycje, a ja poprowadzę niewielki oddział do Stratholmu i rozpocznę rzeź. Musimy powstrzymać i oczyścić zarażonych dla dobra całego Lordaeronu!', '', 0),
(27535, 'plPL', 'Wszyscy wyglądają na gotowych. Pamiętajcie, ci ludzie są zarażeni zarazą i wkrótce umrą. Musimy oczyścić Stratholm, by chronić resztę Lordaeronu przed Plagą. Ruszamy.', '', 0),
(27547, 'plPL', 'Książę Arthasie, chwała Światłości! Wielu ludzi w mieście zaczęło ciężko chorować, możesz nam pomóc?', 'Książę Arthasie, chwała Światłości! Wielu ludzi w mieście zaczęło ciężko chorować, możesz nam pomóc?', 0),
(27548, 'plPL', 'Mogę wam pomóc jedynie czystą śmiercią.', '', 0),
(27549, 'plPL', 'Co? To niemożliwe!', 'Co? To niemożliwe!', 0),
(27552, 'plPL', 'O nie...', 'O nie...', 0),
(27553, 'plPL', 'To był dopiero początek.', '', 0),
(27577, 'plPL', 'Nie pozwolę na to, Mal\'Ganisie! Lepiej, by ci ludzie zginęli z mojej ręki, niż po śmierci służyli ci jako niewolnicy!', '', 0),
(27584, 'plPL', 'Mal\'Ganis wyśle swoje sługi z Plagi, by nam przeszkodzić. Ci z was, którzy mają najmocniejszą stal i magię, wyruszą i ich zniszczą. Resztę moich sił poprowadzę, by oczyścić Stratholm z zarażonych.', '', 0),
(27800, 'plPL', 'Za mną, znam drogę.', '', 0),
(27811, 'plPL', 'Ach, wreszcie przybyłeś, książę Arthasie. Zjawiasz się w ostatniej chwili.', 'Ach, wreszcie przybyłeś, książę Arthasie. Zjawiasz się w ostatniej chwili.', 0),
(27812, 'plPL', 'Tak, cieszę się, że zdążyłem do was przed zarazą.', '', 0),
(27814, 'plPL', 'Co to za czary?', '', 0),
(27815, 'plPL', 'Nie musisz rozumieć, Arthasie. Musisz tylko umrzeć.', 'Nie musisz rozumieć, Arthasie. Musisz tylko umrzeć.', 0),
(27840, 'plPL', 'Wygląda na to, że Mal\'Ganis ma w swoim arsenale coś więcej niż Plagę. Musimy się spieszyć.', '', 0),
(27882, 'plPL', 'Znów te plugawe czary! Bądźcie gotowi na wszystko!', '', 0),
(27901, 'plPL', 'Uważajcie na plecy: otoczyli nas w tej sali.', '', 0),
(27902, 'plPL', 'Mal\'Ganis nie ułatwia nam zadania.', '', 0),
(27904, 'plPL', 'Są bardzo uparci.', '', 0),
(27905, 'plPL', 'Co jeszcze może postawić mi na drodze?', '', 0),
(27906, 'plPL', 'Najszybsza droga do Mal\'Ganisa prowadzi za tamtym regałem z książkami.', '', 0),
(27916, 'plPL', 'Robię, co muszę, dla Lordaeronu, i ani twoje słowa, ani czyny mnie nie powstrzymają.', '', 0),
(28040, 'plPL', 'To zajmie tylko chwilę.', '', 0),
(28041, 'plPL', 'Ulżyło mi, że to tajne przejście wciąż działa.', '', 0),
(28045, 'plPL', 'Odpocznijcie chwilę i złapcie oddech, ale wkrótce musimy ruszać dalej.', '', 0),
(28047, 'plPL', 'Dość tego, musimy ruszać. Mal\'Ganis czeka.', '', 0),
(28048, 'plPL', 'Wreszcie trochę szczęścia. Aleja Targowa jeszcze się nie zajęła ogniem. Mal\'Ganis ma być na Placu Krzyżowców, tuż przed nami. Powiedzcie, kiedy będziecie gotowi ruszać dalej.', '', 0),
(28520, 'plPL', 'Zakończymy to od razu, Mal\'Ganisie. Tylko ty... i ja.', '', 0),
(28529, 'plPL', 'Jeśli będzie trzeba, będę cię ścigał aż na kraniec świata! Słyszysz? Aż na kraniec świata!', '', 0),
(28530, 'plPL', 'Dobrze się dziś spisaliście. Wszystko, co zostawił Mal\'Ganis, należy do was. Weźcie to jako nagrodę. Ja muszę teraz zacząć przygotowania do wyprawy do Północnej Grani.', '', 0),
(28562, 'plPL', 'Przejdźmy tędy jak najszybciej. Jeśli nie zabiją nas nieumarli, zrobi to ogień.', '', 0),
(28563, 'plPL', 'Sprawiedliwości stanie się zadość.', '', 0),
(28836, 'plPL', '', '$GPowinieneś:Powinnaś; teraz trzymać się blisko Arthasa!', 0),
(28890, 'plPL', 'Czempioni, natychmiast spotkajcie się ze mną w ratuszu. Musimy zanieść walkę do Mal\'Ganisa.', 'Czempioni, natychmiast spotkajcie się ze mną w ratuszu. Musimy zanieść walkę do Mal\'Ganisa.', 0),
(29562, 'plPL', '', 'Co ty robisz tak daleko z tyłu? Musisz natychmiast wracać do Stratholmu!$B$BMam cię teleportować do Stratholmu?', 0),
(29578, 'plPL', '', 'Znajdź ukryte skrzynie z zarażonym zbożem i użyj na nich tajemnego zakłócacza!$B$BWtedy Arthas będzie miał dowody, których potrzebuje, by rozpocząć rzeź Stratholmu.', 0),
(30509, 'plPL', '', 'Dobra robota ze skrzyniami! Przyjdź do mnie przed Stratholm po kolejne zadanie!', 0),
(31322, 'plPL', 'Hej! Przestań myszkować w mojej piwnicy! Wynocha!', '', 0),
(31323, 'plPL', 'Co $grobiłeś:robiłaś; w mojej piwnicy? Wszyscy boją się zatrutej żywności, a ostatnie, czego mi trzeba, to obcy grzebiący w moich zapasach! Sio!', '', 0),
(31324, 'plPL', 'Nie uważacie, że to wszystko zakrawa na paranoję?', '', 0),
(31325, 'plPL', 'Rozkaz to rozkaz. Jak książę każe skakać...', '', 0),
(31326, 'plPL', 'Nie da się ukryć, że to dziwny rozkaz. Podejrzana żywność? Według tej definicji należałoby aresztować Belfasta!', '', 0),
(31327, 'plPL', 'SŁYSZAŁEM TO! Żadnego piwa więcej dla ciebie! Ani kropli!', '', 0),
(31355, 'plPL', 'Nie mogę sobie pozwolić, żeby cię oszczędzić.', '', 0),
(31356, 'plPL', 'Jedna przeszkoda mniej.', '', 0),
(31581, 'plPL', 'Jak mam pomóc miastu w tak powszechnym kryzysie?', '', 0),
(31582, 'plPL', 'Wszyscy chorują – to epidemia!', '', 0),
(31583, 'plPL', 'Żadne lekarstwo nie działa – całe miasto zachorowało...', '', 0),
(31584, 'plPL', 'Żołnierze sieją panikę plotkami o zepsutej żywności. Sąsiedzi oskarżają się nawzajem o otrucie. W mieście zapanuje chaos!', '', 0),
(31586, 'plPL', 'Jestem bezradny. Cóż może zrobić jeden prosty człowiek w obliczu katastrofy?', '', 0),
(31587, 'plPL', 'Modlę się, żeby ta niemoc była tylko od wrzodów ze stresu...', '', 0),
(31716, 'plPL', 'Dzień dobry. Mistrza Frasa Siabiego obecnie nie ma. Zapraszamy jutro do sklepu „Przedni tytoń Frasa Siabiego”! Bip!', 'Dzień dobry. Mistrza Frasa Siabiego obecnie nie ma. Zapraszamy jutro do sklepu „Przedni tytoń Siabiego”! Bip!', 0),
(31720, 'plPL', '', 'Mam nadzieję, że nie przychodzisz tu szukać zwady. Na ulicach jest dziś zbyt wielu rozgniewanych ludzi.', 0),
(31721, 'plPL', '', 'Słuchaj, tarcze ci dziś sprzedam, ale maczug nie. Ostatnie, czego chcę, to żeby ktoś niewinny dostał w łeb moją bronią.', 0),
(31722, 'plPL', '', 'Nie wiem, jak długo jeszcze dziś pobędę otwarta przy tym całym zamieszaniu na zewnątrz. Jeśli trzeba ci coś naprawić, rzucę okiem.', 0),
(31724, 'plPL', '„Kamienna Wrona” jest dziś zamknięta, przykro mi. Za dużo obaw o zdrowie, a nie zamierzam narażać Eda na oskarżenia, że niby ludzie przez niego chorują.', '', 0),
(31729, 'plPL', 'Nie lubię zawodzić ludzi, ale „Kamienna Wrona” jest zamknięta. Skoro ewakuowano dzieci z sierocińca, nie widzę powodu, żebyśmy i my byli otwarci.', '', 0),
(31730, 'plPL', '', 'Co to za zamieszanie na zewnątrz?', 0),
(31731, 'plPL', '', 'Czy coś się dzieje? Słyszę gniewne głosy.', 0),
(31732, 'plPL', '', 'Ostatnio wszystko jest takie dziwne...', 0),
(31837, 'plPL', 'Moja żona i dzieci leżą chorzy w łóżkach przez truciznę, którą mi sprzedałaś!', 'Mój mąż i dzieci leżą chorzy w łóżkach przez truciznę, którą mi sprzedałaś!', 0),
(31838, 'plPL', '', 'To nie przez moje jedzenie!', 0),
(31839, 'plPL', 'Nie próbuj się z tego wykręcić!', 'Nie próbuj się z tego wykręcić!', 0),
(31840, 'plPL', '', 'Proszę, to nie moja wina! Jeśli... jeśli oddam ci pieniądze, może pójdziesz z tym do uzdrowiciela? Nie wiem, czego ode mnie oczekujesz!', 0),
(31842, 'plPL', 'To... nie, zatrzymaj sobie swoje brudne pieniądze! One nie pomogą mojej rodzinie!', 'To... nie, zatrzymaj sobie swoje brudne pieniądze! One nie pomogą mojej rodzinie!', 0),
(32023, 'plPL', '', 'Świetna robota! Arthas bezpiecznie zmierza do Północnej Grani!', 0),
(32024, 'plPL', 'Tak, proszę!', 'Tak, proszę!', 0),
(32032, 'plPL', 'Myślę, że to twoje zboże nas truje!', 'Myślę, że to twoje zboże nas truje!', 0),
(32035, 'plPL', 'Wszystko było dobrze, dopóki nie zjedliśmy tego twojego skażonego zboża!', 'Wszystko było dobrze, dopóki nie zjedliśmy tego twojego skażonego zboża!', 0),
(32044, 'plPL', 'Proszę, ja tylko dostarczam towar!', '', 0),
(32057, 'plPL', 'Gdzie jest Barthilas?!', 'Gdzie jest Barthilas?!', 0),
(32058, 'plPL', 'Chcemy rozmawiać z sędzią!', 'Chcemy rozmawiać z sędzią!', 0),
(32059, 'plPL', 'Co mamy robić?!', 'Co mamy robić?!', 0),
(32060, 'plPL', 'Potrzebujemy przywództwa!', 'Potrzebujemy przywództwa!', 0),
(32061, 'plPL', 'Przestań się ukrywać, Barthilasie!', 'Przestań się ukrywać, Barthilasie!', 0),
(32062, 'plPL', 'Przepuśćcie nas!', 'Przepuśćcie nas!', 0),
(32063, 'plPL', 'Wywleczemy cię tu, jeśli będzie trzeba!', 'Wywleczemy cię tu, jeśli będzie trzeba!', 0),
(32068, 'plPL', '', 'Sędzia jest bardzo zajęty.', 0),
(32069, 'plPL', '', 'Proszę wracać do domów.', 0),
(32070, 'plPL', '', 'Proszę wszystkich o spokój...', 0),
(32071, 'plPL', '', 'Sędzia Barthilas jest w tej chwili niedostępny...', 0),
(32073, 'plPL', '', 'Proszę tam nie wchodzić!', 0),
(32074, 'plPL', '', 'Proszę nie przeszkadzać sędziemu!', 0),
(32560, 'plPL', 'Dość, Michaelu. Interes i tak cierpi przez tę panikę. Liczy się każdy miedziak.', '', 0),
(32569, 'plPL', '%s niechętnie kiwa głową.', '', 0),
(32570, 'plPL', 'Nie mogę się z tym spierać.', '', 0),
(32571, 'plPL', 'Żołnierze wykonują ważną pracę. Bezpieczeństwo ludzi jest ważniejsze, Mal, jeśli zależy ci, żeby twoi klienci dożyli kolejnego dnia i mogli coś u ciebie wydać.', '', 0),
(32572, 'plPL', 'Nie martwcie się za bardzo. Do końca mojej zmiany nie znaleźliśmy tu ani okruszka skażonego zboża.', '', 0),
(32573, 'plPL', 'Dzięki Światłości.', '', 0),
(32670, 'plPL', '', 'O nie! Poszukiwacze przygód, stało się coś strasznego! Jeden z moich towarzyszy został pojmany przez Nieskończone Stado i robią mu coś okropnego!$B$BOchrona Arthasa wciąż jest waszym najważniejszym zadaniem, ale jeśli szybko zadziałacie, możecie ocalić Strażnika Czasu!', 0),
(32678, 'plPL', '', 'Poszukiwacze przygód, musicie się spieszyć! Strażnik Czasu długo już nie wytrzyma!', 0),
(32679, 'plPL', '', 'Ledwo wyczuwam Strażnika Czasu! Jego linia czasu szybko się rozmywa!', 0),
(36010, 'plPL', 'Ruszajmy dalej.', 'Ruszajmy dalej.', 0),
(39667, 'plPL', 'Chromie, ty i ja dobrze wiemy, co się wydarzy w tym strumieniu czasu. To wszystko już było. Możesz nas po prostu przenieść od razu do prawdziwej akcji?', 'Chromie, ty i ja dobrze wiemy, co się wydarzy w tym strumieniu czasu. To wszystko już było. Możesz nas po prostu przenieść od razu do prawdziwej akcji?', 0),
(39668, 'plPL', '', 'No tak, już cię tu widziałam! Jak mogłam zapomnieć?$B$BJeśli chcesz, mogę cię teraz teleportować do Stratholmu.', 0);
